7	// Per-book-update microstructure signals: Order Flow Imbalance (OFI) and
8	// microprice (plan: .claude/plans/microstructure-signals.md, steps 2-3).
9	//
10	// Design note: this wraps OrderBookFlat rather than adding fields to it, so
11	// the book keeps a single responsibility and its latency benchmarks stay
12	// comparable with docs/perf/01-flat-book.md. The engine applies each parsed
13	// message to the book, snapshots top-of-book, and emits one MicroEvent per
14	// update.
15	//
16	// OFI follows the best-level definition of Cont, Kukanov & Stoikov (2014),
17	// "The Price Impact of Order Book Events": with best bid (P_b, q_b) and best
18	// ask (P_a, q_a), the event-n contribution is
19	//
20	//   e_n =  1{P_b_n >= P_b_{n-1}} * q_b_n  -  1{P_b_n <= P_b_{n-1}} * q_b_{n-1}
21	//        - 1{P_a_n <= P_a_{n-1}} * q_a_n  +  1{P_a_n >= P_a_{n-1}} * q_a_{n-1}
22	//
23	// Positive e_n = net buying pressure (bid depth added, ask depth consumed).
24	//
25	// Microprice is the depth-weighted mid: with imbalance I = q_b / (q_b + q_a),
26	//   microprice = I * P_a + (1 - I) * P_b
27	// It leans toward the side with LESS depth's price being hit next — a better
28	// short-horizon fair-value estimate than the plain mid.
29	
30	namespace itch {
31	
32	struct MicroEvent {
33	    uint64_t timestamp_ns;   // ITCH ns-since-midnight of the triggering message
34	    double   ofi;            // per-event OFI increment e_n, in shares (signed)
35	    double   microprice;     // depth-weighted mid, in dollars
36	    double   best_bid;       // dollars
37	    double   best_ask;       // dollars
38	    uint32_t bid_size;       // shares at best bid
39	    uint32_t ask_size;       // shares at best ask
40	};
41	
42	class MicrostructureEngine {
43	public:
44	    // Same construction contract as OrderBookFlat: the instrument's expected
45	    // fixed-point tick range must be declared up front.
46	    MicrostructureEngine(uint32_t min_price_raw, uint32_t max_price_raw,
47	                         uint32_t tick_size = 1)
48	        : book_(min_price_raw, max_price_raw, tick_size) {}
49	
50	    void on_add(const AddOrder& m) {
51	        book_.add(m.order_ref, m.side, m.price, m.shares);
52	        emit(m.timestamp_ns);
53	    }
54	    void on_execute(const ExecuteOrder& m) {
55	        book_.execute(m.order_ref, m.executed_shares);
56	        emit(m.timestamp_ns);
57	    }
58	    // Partial cancel ('X'): same book mechanics as an execution — reduce the
59	    // resting order's shares, drop it at zero. Skipping these leaves phantom
60	    // depth (observed as a permanently crossed top-of-book on real data).
61	    void on_cancel(const CancelOrder& m) {
62	        book_.execute(m.order_ref, m.canceled_shares);
63	        emit(m.timestamp_ns);
64	    }
65	    void on_delete(const DeleteOrder& m) {
66	        book_.del(m.order_ref);
67	        emit(m.timestamp_ns);
68	    }
69	    void on_replace(const ReplaceOrder& m) {
70	        book_.replace(m.old_order_ref, m.new_order_ref, m.shares, m.price);
71	        emit(m.timestamp_ns);
72	    }
73	
74	    // Ready-made visitor for parse_buffer(); the engine must outlive it.
75	    MessageVisitor visitor() {
76	        MessageVisitor v;
77	        v.on_add     = [this](const AddOrder& m)     { on_add(m); };
78	        v.on_execute = [this](const ExecuteOrder& m) { on_execute(m); };
79	        v.on_cancel  = [this](const CancelOrder& m)  { on_cancel(m); };
80	        v.on_delete  = [this](const DeleteOrder& m)  { on_delete(m); };
81	        v.on_replace = [this](const ReplaceOrder& m) { on_replace(m); };
82	        return v;
83	    }
84	
85	    const std::vector<MicroEvent>& events() const { return events_; }
86	    // Updates while one book side was empty: no event can be computed there.
87	    uint64_t skipped_one_sided() const { return skipped_one_sided_; }
88	    const OrderBookFlat& book() const { return book_; }
89	
90	private:
91	    void emit(uint64_t timestamp_ns) {
92	        const TopOfBook tob = book_.top_of_book();
93	        if (!tob.best_bid || !tob.best_ask) {
94	            // A one-sided book has no spread: neither OFI's best-level deltas
95	            // nor microprice are defined. Count and move on; prev_* keeps the
96	            // last two-sided state so OFI resumes coherently.
97	            ++skipped_one_sided_;
98	            return;
99	        }
100	        const uint32_t bid_raw = tob.best_bid->price_raw;
101	        const uint32_t ask_raw = tob.best_ask->price_raw;
102	        const uint32_t q_b     = tob.best_bid->shares;
103	        const uint32_t q_a     = tob.best_ask->shares;
104	
105	        double e = 0.0;
106	        if (have_prev_) {
107	            if (bid_raw >= prev_bid_raw_) e += static_cast<double>(q_b);
108	            if (bid_raw <= prev_bid_raw_) e -= static_cast<double>(prev_q_b_);
109	            if (ask_raw <= prev_ask_raw_) e -= static_cast<double>(q_a);
110	            if (ask_raw >= prev_ask_raw_) e += static_cast<double>(prev_q_a_);
111	        }
112	
113	        const double p_b = bid_raw / 10000.0;
114	        const double p_a = ask_raw / 10000.0;
115	        const double micro =
116	            (static_cast<double>(q_b) * p_a + static_cast<double>(q_a) * p_b) /
117	            (static_cast<double>(q_b) + static_cast<double>(q_a));
118	
119	        events_.push_back(MicroEvent{timestamp_ns, e, micro, p_b, p_a, q_b, q_a});
120	
121	        prev_bid_raw_ = bid_raw;
122	        prev_ask_raw_ = ask_raw;
123	        prev_q_b_     = q_b;
124	        prev_q_a_     = q_a;
125	        have_prev_    = true;
126	    }
127	
128	    OrderBookFlat book_;
129	    std::vector<MicroEvent> events_;
130	    uint64_t skipped_one_sided_ = 0;
131	
132	    bool     have_prev_    = false;
133	    uint32_t prev_bid_raw_ = 0;
134	    uint32_t prev_ask_raw_ = 0;
135	    uint32_t prev_q_b_     = 0;
136	    uint32_t prev_q_a_     = 0;
137	};
138	
139	}  // namespace itch
